mapper.select:
SELECT RP.*, P.ImgUrl AS ProdImgName
FROM shopion.tPrfRecentProd RP
INNER JOIN shopion.tPrdProd P ON RP.ProdCode = P.ProdCode

    AND RP.SessonId = #{pSessonId}
    AND RP.ProdCode = #{pProdCode}

ORDER BY RP.RegistDate DESC
LIMIT #{pPageOffset}, #{pPageSize}

SELECT COUNT(*) FROM shopion.tPrfRecentProd

    AND SessonId = #{pSessonId}
    AND ProdCode = #{pProdCode}
